SELECT /* LGUTLC00090.retrieveDynamicQueryList */ a.query_id , a.query_name , a.description AS query_desc , a.access_level , b.common_code_name AS access_level_name , a.access_group FROM XXLGE_QUERY a , ( SELECT lct.code_type_code , lcc.common_code , lccm.common_code_name FROM LGCOM_CODE_TYPE_CODE_C lct , LGCOM_COMMON_CODE_C lcc , LGCOM_COMMON_CODE_MULTI_LANG_C lccm WHERE lct.code_type_code = lcc.code_type_code AND lct.code_type_code = lccm.code_type_code AND lcc.common_code = lccm.common_code AND lcc.company_id = lccm.company_id AND lcc.inventory_organization_id = lccm.inventory_organization_id AND lcc.code_type_code = lccm.code_type_code AND lcc.use_flag = 'Y' AND lccm.language_code = #{USER_SESSION.languageCode} AND lcc.code_type_code = 'LGCOM_DYNAMIC_ACCESSL_LEVEL' AND NVL(lcc.apply_start_date, SYSDATE) >= SYSDATE AND NVL(lcc.apply_end_date, SYSDATE) <= SYSDATE ) b WHERE a.access_level = b.common_code(+) AND a.access_group = #{accessGroup}
AND UPPER(a.query_name) LIKE UPPER(#{queryName}) || '%'
ORDER BY a.access_group, a.query_name

mapper.update:
UPDATE /* LGUTLC00090.updateDynamicQueryData */
       XXLGE_QUERY
   SET query_name        = #{queryName}
     , description       = #{queryDesc}
     , distinct_flag     = #{distinctFlag}
     , hint_clause       = #{hintClause}
     , from_clause       = #{fromClause}
     , where_clause      = #{whereClause}
     , order_by_clause   = #{orderByClause}
     , access_level      = #{accessLevel}
     , access_group      = #{accessGroup}
     , last_updated_by   = #{USER_SESSION.applicationUserId}
     , last_update_date  = SYSDATE
     , last_update_login = #{USER_SESSION.applicationUserId}
 WHERE query_id          = #{queryId}

