INSERT INTO /* LGUTLC00090.insertDynamicQueryColumnData */
            XXLGE_QUERY_COLUMNS (
    query_id,seq,prompt,field,
    data_type,length,width,format_mask
) VALUES (
    #{queryId},#{columnSeq},#{columnPrompt},#{columnField},
    #{dataType},#{columnLength},#{columnWidth},#{formatMask}
)

mapper.update:
UPDATE /* LGUTLC00090.updateDynamicQueryColumnData */
       XXLGE_QUERY_COLUMNS
   SET prompt      = #{columnPrompt}
     , field       = #{columnField}
     , data_type   = #{dataType}
     , length      = #{columnLength}
     , width       = #{columnWidth}
     , format_mask = #{formatMask}
 WHERE query_id    = #{queryId}
   AND seq         = #{columnSeq}

mapper.delete:
DELETE FROM /* LGUTLC00090.deleteDynamicQueryColumnData */
            XXLGE_QUERY_COLUMNS
      WHERE query_id = #{queryId}
        AND seq      = #{columnSeq}

mapper.update:
UPDATE /* LGUTLC00090.updateDynamicQueryParamData */
       XXLGE_QUERY_PARAMETERS
   SET para_name       = #{paraName}
     , type            = #{paraType}
     , distinct_flag   = #{distinctFlag}
     , code_col        = #{codeCol}
     , desc_col        = #{descCol}
     , format_mask     = #{formatMask}
     , from_clause     = #{fromClause}
     , where_clause    = #{whereClause}
     , order_by_clause = #{orderByClause}
 WHERE ROWID           = (SELECT ROWID
                            FROM XXLGE_QUERY_PARAMETERS
                           WHERE query_id  = #{queryId}
                             AND para_name = #{orgParaName})

UPDATE /* LGUTLC00090.updateDynamicQueryParamValueData */
       XXLGE_QUERY_PARAMETER_VALUE
   SET para_name         = #{paraName}
     , default_value     = #{defaultValue}
     , required_flag     = #{requiredFlag}
     , lsat_updated_by   = #{sessionUserId}
     , last_update_date  = SYSDATE
     , last_update_login = #{sessionUserId}
 WHERE ROWID           = (SELECT ROWID
                            FROM XXLGE_QUERY_PARAMETER_VALUE
                           WHERE query_id  = #{queryId}
                             AND para_name = #{orgParaName})
